export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凌晨一點五十八分。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "大廳只開了一半的燈。管理員的櫃台空著，椅背上掛著一件褪色的夾克，收音機沒關，用很小的音量播著老歌，像有人在隔壁房間自言自語。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "天花板那根日光燈一直在嗡嗡響，閃一下，又撐住。信箱牆上貼滿了通水管和搬家公司的貼紙，一層蓋過一層，像這棟樓的年輪。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "(內心)四十年的大樓。燈管大概也四十年。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "妳到了沒？", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "方芮的聲音從九樓傳下來，隔著好幾層水泥和一支手機，聽起來比平常遠。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "到了。沒人。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "廢話，兩點誰會在大廳。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "電話那頭有被子摩擦的沙沙聲。許念幾乎看得見她——縮在客廳那張二手沙發上，抱著抱枕，一邊害怕一邊興奮。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "(內心)提議的人躲在被窩裡。執行的人站在大廳。很公平。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "事情是從十一點開始的。期末報告寫到一半，兩個人都不想動，方芮滑到一篇文章，標題寫著「電梯遊戲，實測」，底下幾百則留言，一半說是假的，一半說不要玩。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "妳不是說妳什麼都不怕？", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "我說我不怕鬼。我怕的是期末報告。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "那正好。搭完回來，報告就不可怕了。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她說得很順，像在說下樓買宵夜。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "(內心)其實只是睡不著。三點睡跟五點睡，差別只是天花板多看兩個小時。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "許念按了上樓鍵。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "樓層顯示是老式的紅色數字，從八開始往下跳，每跳一格都要猶豫一下。纜線在井道裡拖動，聲音很長、很沉，像有什麼東西在牆壁裡翻身。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "我再唸一次規則。第一，一個人搭。中途有人要進來，就出去，改天再玩。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "第二，按四、二、六、二、十。每到一層都不要出去，門關了再按下一個。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "第三，到十樓以後按五。五樓可能會有一個女人走進來。不要跟她說話。不要看她的臉。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "如果她先跟我說話呢？", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "……文章沒寫。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "(內心)很專業。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "第四，她進來以後按一。如果電梯往下，就是失敗，回家睡覺。如果它往上——", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "方芮停了一下。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "到了十樓，按鈕就不會再有反應了。想回來，只能按一，只能按一次。最後一條寫：如果妳走出去，不要回頭。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "叮。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "門往兩邊滑開，左邊那扇總是慢半拍，像腿不太好的老人。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.XuNian, character: "許念", dialogue: "(內心)外婆說過，半夜不要照鏡子，有人叫名字不要回頭應。外婆沒說過電梯。", background: Background.Root_Act1_S0, portrait: Portrait.XuNian_Base },
    { characterId: CharacterId.FangRui, character: "方芮", dialogue: "念念。電話不要掛喔。", background: Background.Root_Act1_S0, portrait: Portrait.FangRui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "許念走進去。", background: Background.Root_Act1_S0 },
];
